mapper.update:
UPDATE CMS_NEWS SET news_name = #{news_name}, sub_news_name = #{sub_news_name}, contents = #{contents}, print_seq = #{print_seq}, link_url = #{link_url}, use_yn = #{use_yn},
org_file_name = #{org_file_name}, server_file_name = #{server_file_name}, file_extension = #{file_extension}, file_size = #{file_size},
modify_id = #{modify_id}, modify_date = SYSDATE WHERE homepage_id = #{homepage_id} AND news_idx = #{news_idx}

